// ============================================================================
// Module: alu_control
// Project: Team Scaler MCA Project - RV32I Pipelined Processor
// Issue: #13 - ALU Control Decoder
//
// Description:
//   A synthesizable, purely combinational ALU control decoder that translates
//   the 2-bit alu_op class from ID/EX (generated by main_control) and the
//   instruction funct3 and funct7 fields into the 4-bit alu_ctrl code consumed
//   by the ALU (Issue #12).
//
// Operation Encodings (Consistent with rtl/stages/alu.v):
//   4'b0000 (ALU_ADD) : 32-bit addition (result = a + b)
//   4'b0001 (ALU_SUB) : 32-bit subtraction (result = a - b)
//
// Decoding Truth Table:
//   +--------+--------+---------+-------------+----------+-----------------------------------------+
//   | alu_op | funct3 | funct7  | Instruction | alu_ctrl | Description                             |
//   +--------+--------+---------+-------------+----------+-----------------------------------------+
//   | 2'b00  | 3'bxxx | 7'bxxxx | ADDI, LW, SW| 4'b0000  | Add / Address class. funct fields are   |
//   |        |        |         |             |          | ignored because immediate bits occupy   |
//   |        |        |         |             |          | these positions in non-R-type encodings.|
//   +--------+--------+---------+-------------+----------+-----------------------------------------+
//   | 2'b01  | 3'b000 | 7'h00   | ADD         | 4'b0000  | R-type addition (rs1 + rs2).            |
//   +--------+--------+---------+-------------+----------+-----------------------------------------+
//   | 2'b01  | 3'b000 | 7'h20   | SUB         | 4'b0001  | R-type subtraction (rs1 - rs2).         |
//   +--------+--------+---------+-------------+----------+-----------------------------------------+
//   | 2'b01  | other  | other   | Unsupported | 4'b0000  | Safe default. Never selects SUB or      |
//   |        |        |         | R-type funct|          | another unsafe operation.               |
//   +--------+--------+---------+-------------+----------+-----------------------------------------+
//   | 2'b10  | 3'bxxx | 7'bxxxx | BEQ, BNE    | 4'b0000  | Branch compare class. Safe default.     |
//   |        |        |         |             |          | Branch decision policy and target       |
//   |        |        |         |             |          | calculation belong to Issue #14.        |
//   +--------+--------+---------+-------------+----------+-----------------------------------------+
//   | 2'b11  | 3'bxxx | 7'bxxxx | Unused      | 4'b0000  | Reserved alu_op. Safe default.          |
//   +--------+--------+---------+-------------+----------+-----------------------------------------+
//
// Architectural Safety Note:
//   Defaulting to ALU_ADD for unsupported funct combinations or unused alu_op
//   values guarantees deterministic, safe ALU operation and prevents unintended
//   subtractions or address corruption. However, a default ALU operation alone
//   does NOT suppress register or memory writes; instruction validity and side
//   effects are strictly qualified by surrounding control logic (such as
//   instruction_decoder.supported, main_control.valid_in, and the pipeline
//   register valid bits).
// ============================================================================

`timescale 1ns/1ps

module alu_control #(
    parameter [3:0] ALU_ADD = 4'b0000,
    parameter [3:0] ALU_SUB = 4'b0001
) (
    input  wire [1:0] alu_op,   // ALU operation class from ID/EX
    input  wire [2:0] funct3,   // Instruction funct3 field
    input  wire [6:0] funct7,   // Instruction funct7 field (or immediate bits)
    output reg  [3:0] alu_ctrl  // Exact ALU operation control code consumed by ALU
);

    always @* begin
        alu_ctrl = ALU_ADD; // Safe default for all unhandled cases
        case (alu_op)
            2'b00: begin
                // Add / Address calculation class (ADDI, LW, SW):
                // Instruction bits in funct7 position are immediate bits, NOT an R-type
                // funct7 field. Map directly to ALU_ADD regardless of funct7 / funct3.
                alu_ctrl = ALU_ADD;
            end

            2'b01: begin
                // R-type arithmetic: distinguish ADD from SUB via funct3 and funct7.
                if (funct3 == 3'b000 && funct7 == 7'h20)
                    alu_ctrl = ALU_SUB;
                else if (funct3 == 3'b000 && funct7 == 7'h00)
                    alu_ctrl = ALU_ADD;
                else
                    alu_ctrl = ALU_ADD; // Safe default: never select SUB for invalid funct
            end

            2'b10: begin
                // Branch comparison class (BEQ, BNE):
                // Branch condition evaluation and target calculation belong to Issue #14.
                // Output safe deterministic default ALU_ADD.
                alu_ctrl = ALU_ADD;
            end

            2'b11: begin
                // Reserved / unused alu_op value:
                // Safe deterministic default ALU_ADD.
                alu_ctrl = ALU_ADD;
            end

            default: begin
                alu_ctrl = ALU_ADD;
            end
        endcase
    end

endmodule
